<template><div><div v-if="notEnrolled" class="premium-card mx-auto max-w-3xl p-10 text-center"><div class="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-red-50 text-red-600"><NavIcon name="shield"/></div><h1 class="mt-4 text-2xl font-bold text-slate-900">Acesso restrito</h1><p class="mt-2 text-sm text-slate-500">Você não está matriculado neste curso. Matricule-se para assistir às aulas.</p><AppLink to="/courses" class="mt-5 inline-flex rounded-xl bg-primary-600 px-4 py-2.5 text-sm font-bold text-white">Ver cursos</AppLink></div><div v-else class="w-full space-y-5"><section class="premium-card overflow-hidden"><div class="flex flex-col gap-4 p-4 sm:flex-row sm:items-center sm:p-5"><CourseCover :course="course" ratio="16/9" fit="cover" loading="lazy" wrapper-class="w-full sm:w-32 sm:h-20 shrink-0 rounded-xl overflow-hidden" img-test-id="courselearn-context-img" fb-test-id="courselearn-context-fallback"/><div class="min-w-0 flex-1"><div class="flex flex-col gap-2 sm:flex-row sm:items-end sm:justify-between"><div><p class="premium-kicker">Sala de aula</p><h1 class="mt-1 truncate text-xl font-bold text-slate-900 sm:text-2xl">{{ course.name }}</h1></div><div class="text-left sm:text-right"><p class="text-xs text-slate-400">Progresso do curso</p><p class="text-lg font-black text-slate-900" data-testid="course-progress-percent">{{ progress.percentage||0 }}%</p></div></div><div class="mt-3 h-2 overflow-hidden rounded-full bg-slate-100"><div class="h-full rounded-full transition-all duration-500" :style="{width:`${progress.percentage||0}%`,background:'var(--brand-primary)'}"></div></div><p class="mt-2 text-xs text-slate-400">Aulas obrigatórias concluídas: <span class="font-bold text-slate-600" data-testid="course-progress-required">{{ progress.completed_required||0 }}/{{ progress.required_lessons||0 }}</span></p></div></div></section><div class="grid grid-cols-1 gap-5 lg:grid-cols-[320px_1fr]"><aside class="premium-card h-fit overflow-hidden lg:sticky lg:top-28"><div class="border-b border-slate-100 px-4 py-4"><p class="premium-kicker">Conteúdo</p><h3 class="mt-1 font-bold text-slate-900">Aulas do curso</h3></div><div class="max-h-[68vh] space-y-1 overflow-y-auto p-2"><button v-for="lesson in lessons" :key="lesson.id" data-testid="lesson-row" :data-lesson-id="lesson.id" :data-lesson-order="lesson.order" :data-lesson-required="lesson.is_required?'true':'false'" :data-lesson-completed="lesson.completed?'true':'false'" @click="selectLesson(lesson)" :class="['flex w-full items-center gap-3 rounded-xl p-3 text-left text-sm transition',selectedLesson?.id===lesson.id?'bg-[var(--brand-primary-soft)] text-slate-900':'text-slate-600 hover:bg-slate-50']"><span :class="['flex h-8 w-8 shrink-0 items-center justify-center rounded-lg text-xs font-black',lesson.completed?'bg-emerald-100 text-emerald-700':selectedLesson?.id===lesson.id?'bg-white text-[var(--brand-primary)]':'bg-slate-100 text-slate-500']">{{ lesson.completed?'✓':lesson.order }}</span><span class="min-w-0 flex-1 truncate font-semibold" data-testid="lesson-title">{{ lesson.title }}</span><span v-if="lesson.completed" data-testid="lesson-completed" class="sr-only">Concluída</span><span v-else-if="lesson.is_free_preview" class="text-[10px] font-bold text-[var(--brand-primary)]">Preview</span><span v-else-if="!lesson.is_required" data-testid="lesson-optional" class="text-[10px] text-slate-400">Opcional</span><span v-else data-testid="lesson-required" class="text-[10px] text-slate-400">Obrigatória</span></button><p v-if="lessons.length===0" class="p-6 text-center text-sm text-slate-400">Nenhuma aula disponível.</p></div></aside><main class="min-w-0"><div v-if="selectedLesson" class="premium-card overflow-hidden"><div class="border-b border-slate-100 px-5 py-4"><p class="text-[10px] font-bold uppercase tracking-[.15em] text-[var(--brand-primary)]">Aula {{ selectedLesson.order }}</p><h2 class="mt-1 font-bold text-slate-900">{{ selectedLesson.title }}</h2></div><div class="bg-slate-950 p-2 sm:p-3"><div class="aspect-video overflow-hidden rounded-xl bg-black shadow-2xl"><video v-if="selectedLesson.content_type==='UPLOAD'" ref="videoRef" :src="watchUrl" controls class="h-full w-full" @timeupdate="onTimeUpdate" @loadedmetadata="onLoaded" @pause="onPause" @ended="onEnded"></video><iframe v-else-if="selectedLesson.content_type==='YOUTUBE'" :src="youtubeEmbedUrl" class="h-full w-full" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe><iframe v-else-if="selectedLesson.content_type==='VIMEO'" :src="vimeoEmbedUrl" class="h-full w-full" frameborder="0" allow="autoplay; fullscreen; picture-in-picture" allowfullscreen></iframe><div v-else class="flex h-full items-center justify-center text-sm text-white/70">Tipo de conteúdo não suportado</div></div></div><div class="p-5"><p v-if="selectedLesson.description" class="text-sm leading-6 text-slate-500">{{ selectedLesson.description }}</p><div class="mt-4 flex items-center gap-3"><AppButton v-if="selectedLesson.content_type!=='UPLOAD'" @click="markComplete(selectedLesson.id)">Marcar como concluída</AppButton></div></div></div><div v-else class="premium-card flex min-h-[380px] items-center justify-center p-10 text-center"><div><div class="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-[var(--brand-primary-soft)] text-[var(--brand-primary)]"><NavIcon name="catalog"/></div><p class="mt-4 font-bold text-slate-800">Selecione uma aula para começar</p><p class="mt-1 text-sm text-slate-400">Seu progresso é salvo automaticamente.</p></div></div></main></div></div></div></template>
<script setup>import{ref,computed,onMounted,onBeforeUnmount}from'vue';import{useRoute}from'vue-router';import api from'../api/client';import{useToast}from'../composables/useToast';import CourseCover from'../components/CourseCover.vue';import AppButton from'../components/AppButton.vue';import AppLink from'../components/AppLink.vue';import NavIcon from'../components/NavIcon.vue';const route=useRoute();const{error:toastError}=useToast();const courseId=route.params.id;const course=ref({}),lessons=ref([]),progress=ref({percentage:0}),selectedLesson=ref(null),watchUrl=ref(null),notEnrolled=ref(false),videoRef=ref(null),currentTime=ref(0),videoDuration=ref(0);let progressInterval=null;const youtubeEmbedUrl=computed(()=>{if(!selectedLesson.value?.video_url)return'';const m=selectedLesson.value.video_url.match(/(?:youtu\.be\/|youtube\.com\/watch\?v=|youtube\.com\/embed\/)([\w-]{11})/);return m?`https://www.youtube.com/embed/${m[1]}`:''});const vimeoEmbedUrl=computed(()=>{if(!selectedLesson.value?.video_url)return'';const m=selectedLesson.value.video_url.match(/vimeo\.com\/(\d+)/);return m?`https://player.vimeo.com/video/${m[1]}`:''});const loadCourse=async()=>{try{course.value=(await api.get(`/api/v1/courses/${courseId}`)).data}catch{/* course load failure — page shows error state via watcher */}};const loadLessons=async()=>{try{lessons.value=(await api.get(`/api/v1/lessons/courses/${courseId}/lessons`)).data}catch(e){if(e.response?.status===403)notEnrolled.value=true}};const loadProgress=async()=>{try{progress.value=(await api.get(`/api/v1/lessons/courses/${courseId}/my-progress`)).data}catch(e){if(e.response?.status===403)notEnrolled.value=true}};const selectLesson=async lesson=>{if(selectedLesson.value)await sendProgress(currentTime.value,false);stopProgressTracking();selectedLesson.value=lesson;currentTime.value=0;videoDuration.value=0;watchUrl.value=null;try{watchUrl.value=(await api.get(`/api/v1/lessons/${lesson.id}/watch-url`)).data.watch_url}catch(e){toastError('Não foi possível carregar o vídeo: '+(e.response?.data?.detail||e.message))}if(lesson.content_type==='UPLOAD')startProgressTracking()};const onTimeUpdate=()=>{if(videoRef.value)currentTime.value=videoRef.value.currentTime};const onLoaded=()=>{if(videoRef.value)videoDuration.value=videoRef.value.duration};const onPause=()=>sendProgress(currentTime.value,false);const onEnded=()=>{if(videoDuration.value)sendProgress(Math.floor(videoDuration.value),true);loadProgress();loadLessons()};const startProgressTracking=()=>{stopProgressTracking();progressInterval=setInterval(()=>{if(videoRef.value)sendProgress(videoRef.value.currentTime,false)},15000)};const stopProgressTracking=()=>{if(progressInterval){clearInterval(progressInterval);progressInterval=null}};const sendProgress=async(seconds,completed)=>{if(!selectedLesson.value)return;try{await api.post(`/api/v1/lessons/${selectedLesson.value.id}/progress`,{watched_seconds:Math.floor(seconds||0),completed});if(completed){loadProgress();loadLessons()}}catch{/* progress save failure — playback continues uninterrupted */}};const markComplete=async lessonId=>{try{await api.post(`/api/v1/lessons/${lessonId}/progress`,{watched_seconds:0,completed:true});loadProgress();loadLessons()}catch{toastError('Erro ao marcar aula como concluída')}};onMounted(()=>{loadCourse();loadLessons();loadProgress()});onBeforeUnmount(()=>{if(selectedLesson.value)sendProgress(currentTime.value,false);stopProgressTracking()})</script>
